using Rows=std::map<std::string,std::vector<uint8_t>>;
struct Mem:mt::SettingsBackend {
 Rows rows;unsigned reads=0,writes=0;int fault=0;bool wrote=false;std::function<void()> hook,readHook;
 int read(const char *key,uint8_t *out,size_t cap)override{++reads;if(wrote&&fault==3)return -EIO;auto i=rows.find(key);if(i==rows.end())return -ENOENT;memcpy(out,i->second.data(),std::min(cap,i->second.size()));if(wrote&&readHook)readHook();return int(i->second.size());}
 int write(const char *key,const uint8_t *in,size_t n)override{++writes;if(hook)hook();if(fault==1)return -EIO;rows[key]={in,in+n};wrote=true;if(fault==4)rows[key].resize(n/2);return fault==2?-EIO:0;}
};
struct Boot:BootSettings {
 Mem &mem;Rows snapshot;unsigned begins=0,ends=0,reads=0;int error=0,readError=0;bool held=false;std::function<void()> hook;
 explicit Boot(Mem &m):mem(m){}
 int begin()override{++begins;if(error)return error;held=true;snapshot=mem.rows;return 0;}
 void end()override{assert(held);held=false;++ends;snapshot.clear();}
 int read(const char *key,uint8_t *out,size_t cap)override{assert(held);++reads;if(hook){auto cb=hook;hook=nullptr;cb();}if(readError)return readError;auto i=snapshot.find(key);if(i==snapshot.end())return -ENOENT;memcpy(out,i->second.data(),std::min(cap,i->second.size()));return int(i->second.size());}
};
struct Context:PkiStorageContext {
 bool allow=true,boot=true,runtime=true;unsigned enters=0,leaves=0,depth=0;
 bool tryEnter()override{++enters;if(!allow)return false;++depth;return true;}
 void leave()override{assert(depth);--depth;++leaves;}
 bool bootQuiescent()const override{return boot;}
 bool quiescent()const override{return runtime;}
};
struct Entropy:EntropySource{unsigned calls=0;bool fail=false;std::function<void()> hook;bool fill(uint8_t *out,size_t n)override{++calls;assert(n==4);if(hook)hook();memset(out,0x39,n);return !fail;}};
struct Key{uint8_t scalar[32]{};IdentityBinding binding;explicit Key(unsigned seed){for(unsigned i=0;i<32;++i)scalar[i]=uint8_t(seed+23*i);scalar[0]&=248;scalar[31]=(scalar[31]&127)|64;crypto_x25519_public_key(binding.publicKey,scalar);binding.node=bench::MtSignature::nodeId(binding.publicKey);binding.generation=1;}IdentityCandidate candidate(){return IdentityCandidate(binding,scalar);}};
struct Fixture {
 Mem mem;Boot boot{mem};Context context;Entropy entropy;Key local{19},peer{71};MonocypherIdentityDeriver deriver;
 Fixture(){IdentityJournal identity;PkiLedger ledger;assert(!identity.load(mem,deriver));assert(!identity.store(mem,deriver,local.candidate(),true));assert(!ledger.load(mem));assert(!ledger.initialize(mem,local.binding.publicKey,local.binding.node,true));assert(!ledger.addTrustedPeer(mem,peer.binding.node,peer.binding.publicKey,true));mem.reads=mem.writes=0;mem.wrote=false;}
 KeyRef activate(PkiStorage &s){assert(!s.prepare());IdentityBinding b;uint32_t p=0;assert(s.preparedBinding(b)&&b.node==local.binding.node);assert(s.preparedPeer(p)&&p==peer.binding.node);assert(!s.runtimeIdentity());assert(!s.activate(local.binding.node));auto *identity=s.runtimeIdentity();assert(identity);KeyRef ref;assert(identity->binding(b,ref));return ref;}
};
